for k in rows[0]:
    if k.lower().startswith(('debito','credito')) or 'ajust' in k.lower():
        try: print(k, round(tot(k),2))
        except Exception as e: print(k,'ERR',e)
d=json.load(open('mes_01/ajustes.json'))
print({k:v for k,v in d.items() if 'balanc' in k.lower() or 'quadr' in k.lower() or 'total' in k.lower()})
"

